<template><section class="builder-panel game-panel"><header class="builder-panel__heading"><strong>◉ Game Preview</strong><small>Preview only</small></header><select :value="preview.referenceAssetId" @change="select($event.target.value)"><option v-for="item in choices" :key="item.id" :value="item.id">{{ item.label }}</option></select><div class="preview-choices"><button v-for="item in choices.slice(0,4)" :key="item.id" :class="[item.id,{active:item.id===preview.referenceAssetId}]" @click="select(item.id)"><span></span><b>{{ item.label }}</b><small>{{ item.brightness }} · {{ item.motion }} motion</small></button></div><label class="custom-background">⇧ Custom background concept<input type="file" accept="image/*" @change="$emit('upload',$event)"></label><p>Preview only · Not included in output</p></section></template>
<script setup>const props=defineProps({preview:Object});const emit=defineEmits(['change','upload']);const choices=[{id:'blank',label:'Blank canvas',brightness:'dark',motion:'low'},{id:'bright-gameplay',label:'Bright gameplay',brightness:'bright',motion:'medium'},{id:'dark-gameplay',label:'Dark gameplay',brightness:'dark',motion:'high'},{id:'high-motion',label:'High-motion gameplay',brightness:'mixed',motion:'high'},{id:'studio',label:'Just Chatting',brightness:'dark',motion:'low'},{id:'camera',label:'Camera-focused',brightness:'mixed',motion:'low'}];function select(id){const choice=choices.find(x=>x.id===id);emit('change',{...props.preview,backgroundType:'reference',referenceAssetId:id,brightness:choice.brightness,motion:choice.motion})}</script>
